"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7394],{1278(e){e.exports=JSON.parse('{"title":"SPA\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \ub300\uccb4\ud558\ub824\ub358 \uac83\uc774 \ubb38\uc81c\uc600\ub2e4.","date":"2025-08-14","coverUrl":"/kudzu-based-bench/assets/notion/6d82233ee9713cdb.png","html":"<h1 data-notion-block-id=\\"24ce548d-8a8e-8079-9a3f-e1dbe38819d7\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"248e548d-8a8e-80bd-bf57-c18a743eec84\\" id=\\"248e548d-8a8e-80bd-bf57-c18a743eec84\\">SPA\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \ub300\uccb4\ud558\ub824\ub358 \uac83\uc774 \ubb38\uc81c\uc600\ub2e4.</h2><a href=\\"https://rwsdk.com/blog/spa-is-dead\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rwsdk.com/blog/spa-is-dead</a><p data-notion-block-id=\\"24be548d-8a8e-8028-92b1-ecfebcbf06eb\\">\uae00\uc758 \uacb0\ub860\uc740 redwoodsdk\uc5d0 <code>initClientNavigation</code>\uac00 \ucd94\uac00\ub418\uc5c8\ub2e4\ub294 \uac83\uc774\uc9c0\ub9cc, SPA\uac00 \ub124\uc774\ud2f0\ube0c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub300\uccb4\ud558\ub824\ub2e4\uac00 \ubcf5\uc7a1\uc131\uc774 \uac15\ud574\uc84c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\ub294 \uc5b4\ub290\uc815\ub3c4 \uc804\ubd80\ud130 \ub17c\uc758\ub418\uace0 \uc788\ub358 \ub0b4\uc6a9\uc785\ub2c8\ub2e4. \uae00\uc5d0\uc11c \ub9d0\ud558\ub4ef\uc774, \uc11c\ubc84 \uc0ac\uc774\ub4dc \ub80c\ub354\ub9c1\uc73c\ub85c \ub3cc\uc544\uac00\uace0, CSS\ub97c \uc0ac\uc6a9\ud574\uc11c \ub124\uc774\ud2f0\ube0c \uc6f9\ucc98\ub7fc \ub9cc\ub4e4\uc5b4\uc57c \ud55c\ub2e4\uace0 \ud558\uae30\ub3c4 \ud558\uace0, <a href=\\"https://jakelazaroff.com/words/the-website-vs-web-app-dichotomy-doesnt-exist/\\">Web app\uacfc Website\ub97c \uc774\ubd84\ubc95\uc801\uc73c\ub85c \ub2e4\ub8e8\ub294 \uac83\uc774 \ubb38\uc81c</a>\ub77c\uace0\ub3c4 \ub9d0\ud569\ub2c8\ub2e4. \uc800 \ub610\ud55c \ubaa8\ub450 \uc11c\ubc84 \ud504\ub808\uc784\uc6cc\ud06c\ub85c \ub3cc\ub9ac\uae30\ubcf4\ub2e4, JS \ud504\ub808\uc784\uc6cc\ud06c\uac00 \uc0dd\uaca8\ub09c \ubc30\uacbd\uc744 \uc774\ud574\ud558\uace0, \uc798 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"24be548d-8a8e-8073-a334-d474c6311a06\\" id=\\"24be548d-8a8e-8073-a334-d474c6311a06\\">React\uc5d0\uc11c Web Workers \uc0ac\uc6a9\ud558\uae30</h2><a href=\\"https://www.rahuljuliato.com/posts/react-workers\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.rahuljuliato.com/posts/react-workers</a><p data-notion-block-id=\\"248e548d-8a8e-8052-a497-e486d51c0273\\">Web Workers\ub97c React\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\uba74 \ub418\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. Worker\uc758 \uc2e4\uc81c \uc0ac\uc6a9\ucc98\ub97c \ucc3e\uc544\ubcf4\uba74 <a href=\\"https://www.notion.com/blog/how-we-sped-up-notion-in-the-browser-with-wasm-sqlite\\">\ub178\uc158\uc758 sqlite \ub3d9\uae30\ud654</a>\uc640 <a href=\\"https://www.youtube.com/watch?v=SVt1-Opp3Wo\\">\ud1a0\uc2a4\uc758 \uc6f9\uc18c\ucf13 \ucd5c\uc801\ud654</a>\uc815\ub3c4\uac00 \uc788\uaca0\ub124\uc694.</p><h1 data-notion-block-id=\\"24ce548d-8a8e-80dc-b5b9-e3be14cc7d21\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"24be548d-8a8e-80b8-9377-dacfbe3d3c70\\" id=\\"24be548d-8a8e-80b8-9377-dacfbe3d3c70\\">React Query\uc5d0\uc11c, <code>select</code>\uac00\ub2a5\uc131\uc744 \ubcf4\ub2e4</h2><a href=\\"https://tkdodo.eu/blog/react-query-selectors-supercharged\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/react-query-selectors-supercharged</a><p data-notion-block-id=\\"24be548d-8a8e-8096-8220-e7ba626aec65\\"><code>select</code>\ub97c \ud1b5\ud574 \ub80c\ub354\ub9c1 \ucd5c\uc801\ud654 \ud558\ub294 \ubc29\ubc95, <code>queryOptions</code>\ub97c \ud1b5\ud55c \ucd94\uc0c1\ud654(\uad8c\uc7a5\ud558\uc9c4 \uc54a\uc2b5\ub2c8\ub2e4!), \ub610\ud55c \uce90\uc2f1\ud558\ub294 \ubc29\ubc95\uae4c\uc9c0 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"24be548d-8a8e-8073-91f0-e6b120e6cdae\\" id=\\"24be548d-8a8e-8073-91f0-e6b120e6cdae\\">tailwindCSS\uc640 CSS \uac19\uc774 \uc0ac\uc6a9 \ub354 \uc798\ud558\uae30</h2><a href=\\"https://thathtml.blog/2025/08/tailwind-and-css-friends-at-last/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://thathtml.blog/2025/08/tailwind-and-css-friends-at-last/</a><p data-notion-block-id=\\"24be548d-8a8e-8022-bc7d-d1a36305e08c\\">tailwindCSS \uc124\uc815\uc744 \ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\uc5ec \uc5b4\ub5bb\uac8c tailwindCSS\uc640 CSS\ub97c \ub3d9\uc2dc\uc5d0 \ucda9\ub3cc\ud558\uc9c0 \uc54a\uace0 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ud558\ub294\uc9c0 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"24ce548d-8a8e-80f6-9633-cf6bdf80a77f\\" id=\\"24ce548d-8a8e-80f6-9633-cf6bdf80a77f\\">SearchBot\uc740 \uc6f9\uc744 \uc870\uac01\uc73c\ub85c \ub9cc\ub4e0\ub2e4.</h2><a href=\\"https://www.jonoalderson.com/conjecture/url-shaped-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jonoalderson.com/conjecture/url-shaped-web/</a><p data-notion-block-id=\\"24ce548d-8a8e-8061-94b2-c050da483621\\">GoogleBot\uac19\uc740 \ubd07\uc774 \uc774\uc804\uc5d0 \ubcf4\uc5ec\uc8fc\ub358 SEO\ubc29\uc2dd\uc73c\ub85c \uc6f9\uc744 \ubd84\uc11d\ud558\uc9c0 \uc54a\uace0, <a href=\\"https://ones-to-watch.ethansup.net/news/post/1fde548d-8a8e-8098-b4b6-fee90c5fafc8#202e548d-8a8e-801b-a529-e89d9731bddc\\">AI\ub294 SEO\ub97c \ubc14\uafc0 \uac83\uc774\ub2e4</a>\uc640 \uac19\uc774 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubd84\uc11d\ud558\uae30 \ub54c\ubb38\uc5d0, \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ucee8\ud150\uce20\uc640 \uc5d4\ub4dc\ud3ec\uc778\ud2b8\ub97c \uc81c\uacf5\ud574\uc57c \ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"24ce548d-8a8e-8085-9d8f-cdd496d9a74f\\" id=\\"24ce548d-8a8e-8085-9d8f-cdd496d9a74f\\">CSS \uba85\uc2dc\ub3c4 \uad00\ub9ac\uc758 \uc774\ud574, \uadf8\ub9ac\uace0 layer</h2><a href=\\"https://www.youtube.com/watch?v=4PkhzoFLJ0Q\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=4PkhzoFLJ0Q</a><h2 data-notion-block-id=\\"248e548d-8a8e-80a5-a9d1-e8457c8e6fb2\\" id=\\"248e548d-8a8e-80a5-a9d1-e8457c8e6fb2\\">\ubc88\uc678: Perplexity\uc758 \ud06c\ub864\ub7ec\ub294 robots.txt\ub97c \ub530\ub974\uc9c0 \uc54a\ub294\ub2e4</h2><a href=\\"https://blog.cloudflare.com/perplexity-is-using-stealth-undeclared-crawlers-to-evade-website-no-crawl-directives/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/perplexity-is-using-stealth-undeclared-crawlers-to-evade-website-no-crawl-directives/</a><p data-notion-block-id=\\"24ce548d-8a8e-8070-a67a-cceb32e00119\\">Perplexity\uc758 \ud06c\ub864\ub7ec\uac00 robots.txt\ub97c \ub530\ub974\uc9c0 \uc54a\ub294 \uac83\uc744 \uac80\uc99d\ud558\ub294 cloudflare\uc758 \uae00\uc785\ub2c8\ub2e4. \uc7ac\ubc0c\ub294 \uc774\uc288\ub85c \ubcf4\uace0 \uac00\uc2dc\uba74 \uc88b\uc744 \ub4ef \ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"24de548d-8a8e-80e9-9270-f8ae2647efc2\\"></p>"}')}}]);